export type Constructor<T = {}> = new (...args: any[]) => T;
export type Handler = (...args: any[]) => void;

export interface EventObject {
    [key: string]: Handler[];
}

export interface EventMethods {
    on(eventName: string, handler: Handler): void;
    off(eventName: string, handler: Handler): void;
    removeAllEvents(): void;
    trigger(eventName: string, ...args: any[]): void;
    __events?: EventObject;
}

export default function withEvents<TBase extends Constructor>(Base: TBase) {
    return class extends Base implements EventMethods {
        __events?: EventObject;

        on(eventName: string, handler: Handler) {
            if (!this.__events) this.__events = {};
            if (!this.__events[eventName]) {
                this.__events[eventName] = [handler];
            } else {
                this.__events[eventName].push(handler);
            }
        }

        off(eventName: string, handler: Handler) {
            if (!this.__events || !this.__events[eventName]) return;
            this.__events[eventName] = this.__events[eventName].filter(h => h !== handler);
        }

        removeAllEvents() {
            this.__events = {};
        }

        trigger(eventName: string, ...args: any[]) {
            if (!this.__events || !this.__events[eventName]) return;
            this.__events[eventName].forEach(h => h(...args));
        }
    };
}